<?php namespace Inilim\Tool\Method\String;\Inilim\Tool\Str :: __include('_contains');function contains(string $haystack,$needles,bool $ignoreCase=false){if($ignoreCase){$haystack=\mb_strtolower($haystack,'UTF-8');}if(!\is_iterable($needles)){$needles=(array) $needles;}foreach($needles as $needle){if($ignoreCase){$needle=\mb_strtolower($needle,'UTF-8');}if($needle!==''&&_contains($haystack,$needle)){return true;}}return false;}